import { defineComponent } from 'vue';

import { SettingsEventEmitter, UserPreferences } from '@game-studio/settings';
import { OverlaysEventEmitter } from '@game-studio/overlays';

import { inversifyContainer } from '../../inversify/container';
import { gameConfig } from '../../models/config-model';
import { device } from '../../services/device';

import { default as GameRulesWrapper } from '../game-rules/wrapper/game-rules-wrapper.vue';
import { default as ChatRules } from './sub-menus/chat-rules/chat-rules.vue';
import { default as RecentWinners } from './sub-menus/recent-winners/recent-winners.vue';

import { Injects } from '../../inversify/injects';
import { sessionDataModel } from '../../models/session-data';
import { userPreferences } from '../../models/user-preferences';
import { demoState } from '../../models/demo-model';
import { eventEmitter } from '../../services/event-emitter';
import { queryStringParams } from '../../services/query-string';
import { getSettingsConfig } from './config';
import { IUserPreferenceConfigEx } from './types';
import { IChatSettingsOption } from './chat-colours';

export default defineComponent({
    name: 'SettingsMenu',
    components: {
        GameRulesWrapper,
        RecentWinners,
        ChatRules
    },
    props: {
        // Chat Rules
        chatRulesUrl: { type: String, required: true },
        // Recent Winners
        // internationalApiClient: { type: Object, required: false },
        apiUrl: { type: String, required: true },
        country: { type: String, requied: true },
        locale: { type: Object, required: true },
    },
    data() {
        return {
            configs: getSettingsConfig(),
            seperateMusicControls: gameConfig.features.seperateMusicSoundControls,
            // Settings Shown or Not
            showLobby: false, // true,
            showDemoMode: false,
            version: gameConfig.version,
            showOneHandedPlay: queryStringParams.isSubGame === true ? false : true,
            showChatColours: queryStringParams.isSubGame === true ? false : true,
            showMyAccount: queryStringParams.isSubGame === true ? false : true,
            showHowToPlay: true,
            showChatSize: queryStringParams.isSubGame === true ? false : true,
            showInGameNotifications: queryStringParams.isSubGame === true ? false : true,
            showRecentWinners: queryStringParams.isSubGame === true ? false : true,
            showChatRules: queryStringParams.isSubGame === true ? false : true,
            hasColourBlindMode: gameConfig.features.colourBlindMode,
            showSessionData: gameConfig.features.showSessionStatusInSettings,
            gameRules: GameRulesWrapper,
            recentWinners: RecentWinners,
            chatRules: ChatRules,
            // Additional Settings From Games
            additionalActionSettings: [] as IUserPreferenceConfigEx[],
            additionalLabelSettings: [] as IUserPreferenceConfigEx[],
            additionalCheckboxSettings: [] as IUserPreferenceConfigEx[],
            additionalMultiCheckboxSettings: [] as IUserPreferenceConfigEx[],
            isOpen: false,
            isSubGame: queryStringParams.isSubGame
        };
    },
    computed: {
        isGameInProgress(): boolean {
            return inversifyContainer.gameModel.isInProgress;
        }
    },
    mounted(): void {
        const settingsVisibilites = inversifyContainer.isBound(Injects.SettingsConfig) ? inversifyContainer.settingsConfig.settingsVisibilites : {};

        this.showOneHandedPlay = !device.type.isDesktop && (settingsVisibilites.showOneHandedPlay ?? this.showOneHandedPlay);
        this.showChatColours = !queryStringParams.isUnAuthDemoMode && (settingsVisibilites.showChatColours ?? this.showChatColours);
        this.showMyAccount = !queryStringParams.isUnAuthDemoMode && device.type.isDesktop && (settingsVisibilites.showMyAccount ?? this.showMyAccount);

        this.showHowToPlay = settingsVisibilites.showHowToPlay ?? this.showHowToPlay;
        this.showChatSize = !queryStringParams.isUnAuthDemoMode && (settingsVisibilites.showChatSize ?? this.showChatSize);
        this.showInGameNotifications = !queryStringParams.isUnAuthDemoMode && (settingsVisibilites.showInGameNotifications ?? this.showInGameNotifications);
        this.showRecentWinners = !queryStringParams.isUnAuthDemoMode && (settingsVisibilites.showRecentWinners ?? this.showRecentWinners);
        this.showChatRules = !queryStringParams.isUnAuthDemoMode && (settingsVisibilites.showChatRules ?? this.showChatRules);
        this.showDemoMode = queryStringParams.locale === 'it-it' && !queryStringParams.isUnAuthDemoMode && demoState.demoGamesRemaining > 0;

        inversifyContainer.soundManager.sfx.muted = !userPreferences.sound;
        inversifyContainer.soundManager.music.muted = !userPreferences.music;

        this.configureAdditionalSettings();
        if (this.showDemoMode) { this.configureDemoModeSetting(); }

        SettingsEventEmitter.on('show', this.showSettings, this);
        SettingsEventEmitter.on('hide', this.hideSettings, this);
        SettingsEventEmitter.on('toggle', this.toggleSettings, this);

        sessionDataModel.sessionDataEvents.on('sessionIdUpdated', this.onSessionIdUpdated, this);
        sessionDataModel.sessionDataEvents.on('ticketIdUpdated', this.onTicketIdUpdated, this);

        if (this.showDemoMode) {
            OverlaysEventEmitter.on('enterDemoMode', () => { this.onDemoModeUpdate(inversifyContainer.strings.overlays.demoMode.inDemoTitle); });
            OverlaysEventEmitter.on('leaveDemoMode', () => { this.onDemoModeUpdate(inversifyContainer.strings.overlays.demoMode.title); });
            OverlaysEventEmitter.on('outOfPlays', () => { this.onDemoModeUpdate(inversifyContainer.strings.overlays.demoMode.title); });
        }
        eventEmitter.on('CHAT_COLOURS_PROVIDED', (chatColours: IChatSettingsOption[]) => {
            this.onChatColoursProvided(chatColours);
        });
    },
    beforeDestroy(): void {
        SettingsEventEmitter.off('show', this.showSettings, this);
        SettingsEventEmitter.off('hide', this.hideSettings, this);
        SettingsEventEmitter.off('toggle', this.toggleSettings, this);

        sessionDataModel.sessionDataEvents.off('sessionIdUpdated', this.onSessionIdUpdated, this);
        sessionDataModel.sessionDataEvents.off('ticketIdUpdated', this.onTicketIdUpdated, this);

        if (this.showDemoMode) {
            OverlaysEventEmitter.off('enterDemoMode', () => { this.onDemoModeUpdate(inversifyContainer.strings.overlays.demoMode.inDemoTitle); });
            OverlaysEventEmitter.off('leaveDemoMode', () => { this.onDemoModeUpdate(inversifyContainer.strings.overlays.demoMode.title); });
            OverlaysEventEmitter.off('outOfPlays', () => { this.onDemoModeUpdate(inversifyContainer.strings.overlays.demoMode.title); });
        }
    },
    methods: {
        configureAdditionalSettings(): void {
            const additionalSettings = gameConfig.additionalSettingsGetter.call(gameConfig);

            for (let i = 0; i < additionalSettings.length; i++) {
                const item = additionalSettings[i].item;
                const config = {} as IUserPreferenceConfigEx;

                switch (item.type) {
                    case 'external-link':
                        config.label = item.name;
                        config.onClick = item.onClick;

                        this.additionalActionSettings.push(config);
                        break;
                    case 'checkbox':
                        const defaultState = item.default === undefined ? true : item.default;
                        // eslint-disable-next-line no-case-declarations
                        const checkboxPref = UserPreferences.getPreference(item.toggle, defaultState, false, false);
                        UserPreferences.setPreference(item.toggle, checkboxPref, false, false);

                        config.key = item.toggle;
                        config.label = item.name;
                        config.default = checkboxPref;
                        config.onClick = item.onClick;

                        this.additionalCheckboxSettings.push(config);
                        break;
                    case 'label-field':
                        config.label = item.label.text;
                        config.value = item.field.text;

                        this.additionalLabelSettings.push(config);
                        break;
                    case 'multi-checkbox':
                        // eslint-disable-next-line no-case-declarations
                        const multiCheckboxPref = UserPreferences.getPreference(item.toggle, item.options[0].value, false, false);
                        UserPreferences.setPreference(item.toggle, multiCheckboxPref, false, false);

                        config.key = item.toggle;
                        config.label = item.name;
                        config.default = multiCheckboxPref;
                        config.onClick = item.onClick;
                        config.options = item.options.map(val => { return { text: val.label, value: val.value }; });

                        this.additionalMultiCheckboxSettings.push(config);
                        break;
                    default:
                        break;
                }
            }
        },
        onSessionIdUpdated(sessionId: string) {
            this.configs.labels.sessionNumber.value = sessionId;
        },
        onTicketIdUpdated(ticketId: string) {
            this.configs.labels.gameNumber.value = ticketId;
        },
        onDemoModeUpdate(newLabel: string) {
            if (this.configs.navigation.demoMode) {
                this.configs.navigation.demoMode.label = newLabel;
            }
        },
        onChatColoursProvided(chatColours: IChatSettingsOption[]) {
            this.configs.userPrefs.chatColour.options = chatColours;
        },
        onClickOutside(): void {
            SettingsEventEmitter.emit('hide');
        },
        showSettings(): void {
            this.setSettingsVisibility(true);
        },
        hideSettings(): void {
            this.setSettingsVisibility(false);
        },
        toggleSettings(): void {
            this.setSettingsVisibility(!this.isOpen);
        },
        setSettingsVisibility(value: boolean): void {
            this.isOpen = value;
            eventEmitter.emit('GLOBAL_SETTINGS_VISIBILITY_CHANGE', value);
        },
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        recentWinnersProps(): Promise<{ [key: string]: any }> {
            return Promise.resolve({
                apiUrl: this.apiUrl,
                country: this.country,
                locale: this.locale
            });
        },
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        chatRulesProps(): Promise<{ [key: string]: any }> {
            return Promise.resolve({
                url: this.chatRulesUrl
            });
        },
        configureDemoModeSetting(): void {
            const item = {
                label: inversifyContainer.strings.overlays.demoMode.title,
                onClick: async () => {
                    demoState.toggleDemoMode();
                }
            };
            const config = {} as IUserPreferenceConfigEx;

            config.label = item.label;
            config.onClick = item.onClick;

            this.additionalActionSettings.push(config);
            this.configs.navigation.demoMode = config;
        }

    }
});
